from pathlib import Path
from html import escape
import json

root=Path(__file__).parent
data=json.loads((root/"profile-data.json").read_text(encoding="utf-8"))
out=root/"dist"
(out/"details").mkdir(parents=True)
profile=data["profile"]
sections=data["sections"]
theme=data.get("theme",{"enabled":False,"default":"system"})

css="""
*{box-sizing:border-box}:root{font:16px/1.65 Inter,ui-sans-serif,system-ui,sans-serif;--bg:#f4f5f8;--ink:#171923;--muted:#686c7a;--surface:#fff;--line:#dfe1e8;--accent:#4936c9;--accent-soft:#eeebff;--warm:#f06449;--shadow:0 24px 65px rgba(28,24,58,.11)}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink)}a{color:var(--accent);text-underline-offset:.2em}.shell{width:min(100% - 2rem,78rem);margin:auto}.topbar{display:flex;align-items:center;justify-content:space-between;min-height:4.5rem;border-bottom:1px solid var(--line)}.wordmark{color:var(--ink);font-weight:850;letter-spacing:-.025em;text-decoration:none}.topbar span{color:var(--muted);font-size:.8rem}.hero{position:relative;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(16rem,.55fr);gap:clamp(2rem,7vw,7rem);align-items:center;padding:clamp(4rem,10vw,8.5rem) 0}.hero:after{content:"";position:absolute;right:-8%;top:10%;width:25rem;height:25rem;border-radius:50%;background:radial-gradient(circle,var(--accent-soft),transparent 68%);z-index:-1}.kicker,.section-label{margin:0 0 1rem;color:var(--warm);font-size:.72rem;font-weight:850;letter-spacing:.16em;text-transform:uppercase}.hero h1{max-width:12ch;margin:0;font-size:clamp(3rem,8vw,6.7rem);line-height:.92;letter-spacing:-.065em}.role{max-width:38rem;margin:1.6rem 0 .6rem;color:var(--accent);font-size:clamp(1.1rem,2vw,1.45rem);font-weight:650}.affiliation{max-width:40rem;color:var(--muted)}.portrait-wrap{position:relative}.portrait-wrap:before{content:"";position:absolute;inset:1rem -1rem -1rem 1rem;border:2px solid var(--warm);border-radius:1.2rem}.portrait{position:relative;display:block;width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:1.2rem;filter:saturate(.9);box-shadow:var(--shadow);transition:transform .3s}.portrait-wrap:hover .portrait{transform:translate(-4px,-4px)}.actions{display:flex;flex-wrap:wrap;gap:.55rem;margin-top:1.6rem}.actions a{padding:.62rem .9rem;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--ink);font-size:.86rem;font-weight:700;text-decoration:none;transition:transform .18s,border-color .18s,color .18s}.actions a:hover{transform:translateY(-2px);border-color:var(--accent);color:var(--accent)}.interests{display:flex;flex-wrap:wrap;gap:.55rem;margin:0;padding:1.25rem 0 3.5rem;border-top:1px solid var(--line);list-style:none}.interests li{padding:.38rem .72rem;border-radius:.35rem;background:var(--accent-soft);color:#3826a2;font-size:.82rem;font-weight:700}.directory{padding:clamp(3rem,7vw,6rem) 0}.directory-head{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin-bottom:2rem}.directory h2{margin:0;font-size:clamp(2rem,4vw,3.4rem);letter-spacing:-.045em}.directory-head p{max-width:32rem;margin:0;color:var(--muted)}.links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.links a{position:relative;min-height:12rem;padding:1.4rem;border:1px solid var(--line);border-radius:.75rem;background:var(--surface);color:var(--ink);text-decoration:none;transition:transform .22s,border-color .22s,box-shadow .22s}.links a:hover{transform:translateY(-5px);border-color:var(--accent);box-shadow:0 18px 38px rgba(28,24,58,.09)}.card-index{display:block;margin-bottom:3rem;color:var(--warm);font:700 .72rem ui-monospace,monospace}.card-title{display:block;padding-right:2rem;font-size:1.08rem;font-weight:800}.card-arrow{position:absolute;right:1.35rem;bottom:1.2rem;color:var(--accent);font-size:1.25rem}.footer{display:flex;justify-content:space-between;gap:1rem;padding:2rem 0 3rem;border-top:1px solid var(--line);color:var(--muted);font-size:.82rem}.detail{width:min(100% - 2rem,66rem);margin:auto}.detail-bar{display:flex;justify-content:space-between;align-items:center;padding:1.3rem 0;border-bottom:1px solid var(--line)}.back{font-weight:750;text-decoration:none}.detail article{margin:clamp(2rem,7vw,6rem) 0;padding:clamp(1.4rem,5vw,4rem);border:1px solid var(--line);border-radius:.85rem;background:var(--surface);box-shadow:var(--shadow)}.detail article h1{margin-top:0;font-size:clamp(2.2rem,6vw,4.5rem);line-height:1;letter-spacing:-.055em}.detail article h2{margin-top:2rem}table{display:block;width:100%;overflow-x:auto;border-collapse:collapse}th,td{padding:.7rem .8rem;border-bottom:1px solid var(--line);text-align:left}th{background:var(--accent-soft);font-size:.76rem;text-transform:uppercase}blockquote{margin-left:0;padding:1rem 1.2rem;border-left:3px solid var(--accent);background:var(--accent-soft)}pre{overflow:auto;padding:1rem;border-radius:.5rem;background:#20212c;color:#f7f7fb}:focus-visible{outline:3px solid #9389e8;outline-offset:3px}@media(max-width:800px){.hero{grid-template-columns:1fr;padding-top:3rem}.portrait-wrap{width:min(80%,20rem)}.links{grid-template-columns:repeat(2,minmax(0,1fr))}.directory-head{display:block}.directory-head p{margin-top:.7rem}}@media(max-width:520px){.shell,.detail{width:min(100% - 1.5rem,78rem)}.topbar span{display:none}.hero h1{font-size:3.2rem}.portrait-wrap{width:72%}.links{grid-template-columns:1fr}.links a{min-height:8.5rem}.card-index{margin-bottom:1.7rem}.footer{display:block}.footer span{display:block;margin-top:.35rem}.detail article{padding:1.25rem}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
"""
css += """html[data-theme=dark]{--bg:#11121a;--ink:#f4f2ff;--muted:#aaa8b8;--surface:#1b1c27;--line:#343545;--accent:#a99cff;--accent-soft:#292542;--warm:#ff8a70;--shadow:0 24px 65px rgba(0,0,0,.35)}@media(prefers-color-scheme:dark){html[data-theme=system]{--bg:#11121a;--ink:#f4f2ff;--muted:#aaa8b8;--surface:#1b1c27;--line:#343545;--accent:#a99cff;--accent-soft:#292542;--warm:#ff8a70;--shadow:0 24px 65px rgba(0,0,0,.35)}}.bar-actions{display:flex;align-items:center;gap:.75rem}.theme-toggle{width:2.45rem;height:2.45rem;border:1px solid var(--line);border-radius:50%;background:var(--surface);color:var(--ink);cursor:pointer;transition:transform .18s,border-color .18s}.theme-toggle:hover{transform:rotate(12deg);border-color:var(--accent)}.directory-head{display:none!important}.back{display:flex;align-items:center;gap:.65rem;color:var(--ink);font-weight:750;text-decoration:none}.back kbd{display:inline-grid;place-items:center;width:2.5rem;height:2.1rem;border:1px solid var(--line);border-bottom-width:3px;border-radius:.45rem;background:var(--surface);color:var(--accent);font:800 1rem ui-monospace,monospace;transform:rotate(-5deg);transition:transform .18s}.back:hover kbd{transform:rotate(0) translateY(-2px)}.back small{color:var(--muted);font-weight:500}table{border:1px solid var(--line);border-radius:.7rem;border-collapse:separate;border-spacing:0;background:var(--surface)}th{background:linear-gradient(135deg,var(--accent-soft),var(--surface));color:var(--accent);letter-spacing:.08em}tr:last-child td{border-bottom:0}tbody tr{transition:background .16s}tbody tr:hover{background:var(--accent-soft)}"""
css += ".interests li{color:var(--accent)}table{display:table!important;width:100%;table-layout:fixed;overflow:visible}th,td{overflow-wrap:anywhere;vertical-align:top}@media(max-width:520px){th,td{padding:.58rem .45rem;font-size:.82rem}}"
css += """.detail article h2{padding-top:1.5rem;border-top:1px solid var(--line)}.detail article h2:first-of-type{padding-top:0;border-top:0}.detail article li{margin:.42rem 0;transition:color .18s,transform .18s}.detail article li:hover{color:var(--accent);transform:translateX(3px)}.skill-group{display:grid;gap:.7rem;margin:1.15rem 0}.skill-label{font-size:.78rem;letter-spacing:.08em;text-transform:uppercase}.skill-pills{display:flex;flex-wrap:wrap;gap:.5rem}.skill-pill{display:inline-flex;padding:.42rem .76rem;border:1px solid var(--line);border-radius:999px;background:var(--accent-soft);color:var(--accent);font-size:.82rem;transition:transform .18s,border-color .18s,background .18s}.skill-pill:hover{transform:translateY(-2px);border-color:var(--accent);background:var(--surface)}.content-action{display:inline-flex;margin:.25rem .25rem .25rem 0;padding:.48rem .8rem;border:1px solid var(--line);border-radius:999px;background:var(--accent-soft);font-size:.82rem;font-weight:750;text-decoration:none;transition:transform .18s,border-color .18s,background .18s}.content-action:hover{transform:translateY(-2px);border-color:var(--accent);background:var(--surface)}article[data-section-type=news] li,article[data-section-type=awards] li,article[data-section-type=service] li{padding:.5rem .7rem;border-radius:.5rem}article[data-section-type=news] li:hover,article[data-section-type=awards] li:hover,article[data-section-type=service] li:hover{background:var(--accent-soft)}"""
(out/"style.css").write_text(css,encoding="utf-8")

theme_script="""<script>(function(){const r=document.documentElement,b=document.querySelector('[data-theme-toggle]');if(!b)return;let v=localStorage.getItem('profile-theme')||r.dataset.theme||'system';const a=x=>{r.dataset.theme=x;const d=x==='dark'||(x==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);b.textContent=d?'☀':'☾';b.setAttribute('aria-label',d?'Switch to light theme':'Switch to dark theme');b.title=b.getAttribute('aria-label')};a(v);b.addEventListener('click',()=>{const d=r.dataset.theme==='dark'||(r.dataset.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches),n=d?'light':'dark';localStorage.setItem('profile-theme',n);a(n)})})()</script>""" if theme.get("enabled") else ""
theme_button='<button class="theme-toggle" type="button" data-theme-toggle aria-label="Switch color theme">☾</button>' if theme.get("enabled") else ""
theme_attrs=f' data-theme="{escape(theme.get("default","system"))}"'
content_script="""<script>(()=>{const a=document.querySelector('article[data-section-type]');if(!a)return;if(a.dataset.sectionType==='skills')a.querySelectorAll('p').forEach(p=>{const s=p.querySelector(':scope > strong');if(!s)return;const v=p.textContent.slice(s.textContent.length).replace(/^\\s*:\\s*/,'').split(',').map(x=>x.trim().replace(/^and\\s+/i,'')).filter(Boolean);if(!v.length)return;const g=document.createElement('div');g.className='skill-group';const l=document.createElement('strong');l.className='skill-label';l.textContent=s.textContent.replace(/:\\s*$/,'');const w=document.createElement('span');w.className='skill-pills';v.forEach(x=>{const i=document.createElement('span');i.className='skill-pill';i.textContent=x;w.appendChild(i)});g.append(l,w);p.replaceWith(g)});if(['projects','custom'].includes(a.dataset.sectionType))a.querySelectorAll('a').forEach(x=>x.classList.add('content-action'))})()</script>"""

def action_links(prefix=""):
    items=[]
    if profile.get("email"): items.append(("Email",f'mailto:{profile["email"]}'))
    items.extend((label.replace("_"," ").title(),url) for label,url in profile.get("links",{}).items() if url)
    if profile.get("cv"): items.append(("Resume",prefix+profile["cv"]))
    return "".join(f'<a href="{escape(url)}">{escape(label)}</a>' for label,url in items)

photo=(f'<div class="portrait-wrap"><img class="portrait" src="{escape(profile["photo"])}" alt="Portrait of {escape(profile["name"])}"></div>' if profile.get("photo") else "")
interests=(f'<ul class="interests">{"".join(f"<li>{escape(item)}</li>" for item in profile.get("research_interests",[]))}</ul>' if profile.get("research_interests") else "")
cards="".join(f'<a href="details/{escape(section["id"])}.html"><span class="card-index">{index:02d} / {escape(section["type"].upper())}</span><span class="card-title">{escape(section["title"])}</span><span class="card-arrow" aria-hidden="true">↗</span></a>' for index,section in enumerate(sections,1))
home=f'''<!doctype html><html lang="en"{theme_attrs}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="description" content="{escape(profile["designation"])} — {escape(profile["name"])}"><link rel="stylesheet" href="style.css"><title>{escape(profile["name"])}</title></head><body><div class="shell"><header class="topbar"><a class="wordmark" href="index.html">{escape(profile["name"])}</a><div class="bar-actions">{theme_button}</div></header><main><section class="hero"><div><p class="kicker">{escape(profile.get("institute", ""))}</p><h1>{escape(profile["name"])}</h1><p class="role">{escape(profile["designation"])}</p><p class="affiliation">{escape(profile.get("department", ""))}</p><div class="actions">{action_links()}</div></div>{photo}</section>{interests}<section class="directory"><div class="links">{cards}</div></section></main><footer class="footer"><strong>{escape(profile["name"])}</strong><span>{escape(profile["designation"])}</span></footer></div>{theme_script}</body></html>'''
(out/"index.html").write_text(home,encoding="utf-8")

for section in sections:
    page=f'''<!doctype html><html lang="en"{theme_attrs}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../style.css"><title>{escape(section["title"])} — {escape(profile["name"])}</title></head><body><div class="detail"><header class="detail-bar"><a class="back" href="../index.html"><kbd>⌫</kbd><span>Back <small>or press Backspace</small></span></a><div class="bar-actions">{theme_button}</div></header><article data-section-type="{escape(section["type"])}"><p class="section-label">{escape(section["type"])}</p><h1>{escape(section["title"])}</h1>{section["html"]}</article></div>{theme_script}{content_script}<script>addEventListener('keydown',e=>{{if(e.key==='Backspace'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.activeElement.isContentEditable){{e.preventDefault();history.length>1?history.back():location.href='../index.html'}}}})</script></body></html>'''
    (out/"details"/f'{section["id"]}.html').write_text(page,encoding="utf-8")
